const fs = require('node:fs')
const path = require('node:path')

const root = path.resolve(__dirname, '..')
const projects = [
  'abertura-chamados-glpi',
  'assistente-vendas-ia',
  'controle-acesso-visao',
  'igreja-casa',
  'relatorio-interativo',
  'scanner-game-free',
  'validador-firewall'
]

const cssRoot = path.join(root, 'assets', 'css')
const projectBase = [
  '/* Generated by tools/optimize-project-assets.cjs. */',
  fs.readFileSync(path.join(cssRoot, 'project-utilities.css'), 'utf8'),
  fs.readFileSync(path.join(cssRoot, 'rdp-project-shell.css'), 'utf8'),
  fs.readFileSync(path.join(cssRoot, 'rdp-project-rebrand.css'), 'utf8')
].join('\n')
fs.writeFileSync(path.join(cssRoot, 'project-base.css'), projectBase, 'utf8')

for (const project of projects) {
  const file = path.join(root, 'projects', project, 'index.html')
  let html = fs.readFileSync(file, 'utf8')

  html = html.replace(/\s*<script\s+src=["']https:\/\/cdn\.tailwindcss\.com\/?["']><\/script>\s*/gi, '\n')
  html = html.replace(/\s*<script>\s*tailwind\.config\s*=\s*\{[\s\S]*?<\/script>\s*/gi, '\n')
  html = html.replace(/\s*<link[^>]+fonts\.googleapis\.com[^>]*>\s*/gi, '\n')
  html = html.replace(/\s*<link[^>]+rel=["']preconnect["'][^>]+fonts\.(?:googleapis|gstatic)\.com[^>]*>\s*/gi, '\n')
  html = html.replace(/\s*<script>\s*window\.ROD_TOUR_DEFINITIONS\s*=\s*\{[\s\S]*?<\/script>\s*/gi, '\n')

  html = html.replace(/\s*<link rel='stylesheet' href='\.\.\/\.\.\/assets\/css\/(?:project-utilities|rdp-project-shell|rdp-project-rebrand)\.css'>\s*/g, '\n')
  const projectBaseLink = "<link rel='stylesheet' href='../../assets/css/project-base.css'>"
  html = html.replace('<!-- RDP_REBRAND_HEAD -->', `<!-- RDP_REBRAND_HEAD -->\n${projectBaseLink}`)

  fs.writeFileSync(file, html, 'utf8')
  console.log(`optimized ${project}`)
}
